// 用途：执行设备协议、配置保留、依赖模型与媒体能力诊断。
using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Net;
using System.Net.Http;
using System.Net.Sockets;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;

namespace CubicDesk {
  public static class Diagnostics {
    static readonly List<object> results=new List<object>();
    static void Assert(bool condition,string message){if(!condition)throw new Exception(message);}
    static void Check(string name,Action test){try{test();results.Add(J.D("test",name,"passed",true));}catch(Exception ex){results.Add(J.D("test",name,"passed",false,"error",ex.Message));}}
    static void CatalogCheck(string name,Action<DependencyCatalog,string> test){Check(name,delegate{string dir=Path.Combine(Store.Data,"temp","dependency-check-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string seed=Path.Combine(dir,"empty.json");File.WriteAllText(seed,J.Stringify(J.D("schema_version",1,"dependencies",new object[0],"apps",new object[0])));try{test(new DependencyCatalog(dir,seed),dir);}finally{Directory.Delete(dir,true);}});}
    public static int Run(string[] args){
      Check("single instance gate signals the existing resident process",delegate{string name="test-"+Guid.NewGuid().ToString("N");using(var first=new SingleInstanceGate(name))using(var second=new SingleInstanceGate(name)){Assert(first.Primary&&!second.Primary,"multiple primary instances");Assert(second.Activate(),"activation failed");Assert(first.ShowEvent.WaitOne(500),"primary did not receive signal");}});
      if(args.Contains("--background-live"))Check("registered startup points to the current background program",delegate{var mode=LoginStartup.Mode;Assert(mode!=LoginStartupMode.Off,"current program is not registered for login startup");Assert(LoginStartup.RegisteredCommand==LoginStartup.CommandFor(mode),"startup command differs from selected mode");Assert(File.Exists(Path.Combine(Store.Root,"CubicDesk.exe")),"registered executable missing");});
      Check("local device address validation",delegate{Assert(DeviceClient.Normalize("http://192.168.137.7/")=="192.168.137.7","normalization");Assert(DeviceClient.Normalize("clocteck-cubic.local")=="clocteck-cubic.local","mDNS");foreach(string invalid in new[]{"https://example.com","8.8.8.8","192.168.1.1/path","127.0.0.1:80"}){bool rejected=false;try{DeviceClient.Normalize(invalid);}catch(ArgumentException){rejected=true;}Assert(rejected,"accepted invalid address: "+invalid);}});
      Check("Cubic identity rejects unrelated HTTP servers",delegate{Assert(!DeviceClient.IsDevice(J.D("ok",true)),"generic JSON accepted");Assert(DeviceClient.IsDevice(J.D("ok",true,"main_path","/main","installed_apps",new object[0],"wifi",J.D("ap_ssid","clocteck-test"))),"Cubic identity rejected");});
      Check("LRC timestamps match device at_ms protocol",delegate{var parsed=MusicBridge.ParseLrc("[offset:-50]\n[00:01.25][00:03.5]第一行\n[00:02.001]第二行\n[00:78.5]invalid");Assert(parsed.Count==3,"timestamp count");Assert(J.Num(parsed[0],"at_ms")==1300,"hundredths offset");Assert(J.Num(parsed[1],"at_ms")==2051,"milliseconds");Assert(J.Num(parsed[2],"at_ms")==3550,"tenths and ordering");Assert(J.Num(MusicBridge.ParseLrc("[offset:+500]\n[00:01]text")[0],"at_ms")==500,"positive offset must advance lyrics");});
      Check("QQ lyrics matching rejects wrong singer and song duration",delegate{var song=J.D("songname","Track (Live)","singer",new[]{J.D("name","Singer")},"interval",200);Assert(QQMusicLyrics.Match(song,"Track (Live)","Singer",200000)>0,"correct match rejected");Assert(QQMusicLyrics.Match(song,"Track (Live)","Other",200000)==0,"wrong singer accepted");Assert(QQMusicLyrics.Match(song,"Track (Live)","Singer",220000)==0,"wrong version accepted");Assert(QQMusicLyrics.Match(song,"Other Track","Singer",200000)==0,"wrong title accepted");});
      Check("lyrics source follows the player and respects manual choice",delegate{Assert(OnlineLyrics.Resolve("auto","QQMusic.exe")=="qq","QQ source");Assert(OnlineLyrics.Resolve("auto","cloudmusic.exe")=="netease","NetEase source");Assert(OnlineLyrics.Resolve("auto","Spotify.exe")=="","unknown player must allow explicit source");Assert(OnlineLyrics.Resolve("netease","QQMusic.exe")=="netease","manual override ignored");});
      Check("NetEase aliases match the same singer without accepting other versions",delegate{var song=NetEaseLyrics.MatchRecord(J.D("name","Track","artists",new[]{J.D("name","New Name (Original Singer)")},"duration",200000));Assert(QQMusicLyrics.Match(song,"Track","Original Singer",200000)>0,"singer alias rejected");Assert(QQMusicLyrics.Match(song,"Track","Unrelated Singer",200000)==0,"different singer accepted");Assert(QQMusicLyrics.Match(song,"Track","Original Singer",230000)==0,"different duration accepted");});
      if(args.Contains("--netease-live"))Check("NetEase public lyric service returns timestamped lyrics",delegate{var result=NetEaseLyrics.Fetch("起风了","买辣椒也用券",325868,CancellationToken.None).GetAwaiter().GetResult();Assert(result.Provider=="netease"&&result.Lines.Count>0,"NetEase lyrics missing");Assert(J.Get(result.Lines[0],"at_ms")!=null,"timestamp missing");});
      Check("Lua form edit preserves unrelated fields and comments",delegate{string source="local config = {}\nconfig.host = \"192.168.0.105\" -- host\nconfig.port = 17865\nconfig.serial_log = true\n-- untouched\nreturn config\n";var fields=ConfigField.ParseLua(source);Assert(fields.Count==3,"parsed "+fields.Count+" fields");var host=fields.First(f=>f.Key=="host");string output=ConfigField.ApplyEdits(source,new[]{new ConfigEdit {Start=host.Start,Length=host.Length,Value=ConfigField.LuaLiteral("电脑\"测试\\目录")}});Assert(output.Contains("-- untouched")&&output.Contains("config.port = 17865"),"lost unrelated data");Assert(ConfigField.ParseLua(output).First(f=>f.Key=="host").Value.ToString()=="电脑\"测试\\目录","string escaping");});
      CatalogCheck("dependency metadata distinguishes unknown from explicitly none",delegate(DependencyCatalog c,string dir){Assert(!c.IngestStoreItem(J.D("app_id","unknown","dependencies",new[]{"lua"})),"device dependency mistaken for PC requirement");Assert(!c.Reviewed("unknown"),"missing metadata marked reviewed");Assert(c.IngestStoreItem(J.D("app_id","none","pc_dependencies",new object[0])),"explicit empty ignored");Assert(c.Reviewed("none")&&c.Requirements("none").Count==0,"explicit none not retained");});
      CatalogCheck("shared dependencies deduplicate and retain manual status",delegate(DependencyCatalog c,string dir){var dep=J.D("id","shared","name","Shared bridge","source","用户维护","custom",J.D("keep",true));c.Upsert("app-a","A",dep,"1.x",false);c.Upsert("app-b","B",dep,"2.x",true);Assert(c.Dependencies.Count==1&&c.Users("shared").Count==2,"shared dependency duplicated");Assert(c.Pending("app-a")==1&&c.Pending("app-b")==0,"optional requirements counted incorrectly");c.Mark("SHARED","ready");var loaded=new DependencyCatalog(dir,Path.Combine(dir,"empty.json"));Assert(loaded.Status("shared")=="ready"&&loaded.Pending("app-a")==0,"manual state not persisted");Assert(J.Bool(J.Map(loaded.Dependency("shared"),"custom"),"keep"),"unknown field lost");Assert(Directory.GetFiles(Path.Combine(dir,"dependency-backups")).Length>0,"catalog backup missing");});
      CatalogCheck("dependency imports cannot assert this computer is ready",delegate(DependencyCatalog c,string dir){c.Merge(J.D("schema_version",1,"dependencies",new[]{J.D("id","bridge","name","Bridge","status","ready")},"apps",new[]{J.D("app_id","demo","reviewed",true,"requirements",new[]{J.D("dependency_id","bridge")})},"dependency-status",J.D("bridge",J.D("status","ready"))));Assert(c.Status("bridge")=="unconfirmed"&&c.Pending("demo")==1,"import trusted external install state");c.Mark("bridge","skipped");c.Merge(c.Export());Assert(c.Status("bridge")=="skipped"&&c.Pending("demo")==1,"import overwrote manual state or skipped required dependency passed");});
      CatalogCheck("invalid dependency imports are rejected before mutation",delegate(DependencyCatalog c,string dir){foreach(string url in new[]{"file:///C:/run.exe","javascript:alert(1)","https://user:password@example.com/"}){bool rejected=false;try{c.Merge(J.D("schema_version",1,"dependencies",new[]{J.D("id","first","name","First"),J.D("id","bad","name","Bad","download_url",url)},"apps",new object[0]));}catch{rejected=true;}Assert(rejected&&c.Dependencies.Count==0,"invalid URL partly imported");}bool malformed=false;try{c.Merge(J.D("schema_version",1,"dependencies","wrong","apps",new object[0]));}catch{malformed=true;}Assert(malformed,"non-array dependencies accepted");});
      CatalogCheck("store refresh preserves curated dependency information",delegate(DependencyCatalog c,string dir){c.Upsert("demo","Demo",J.D("id","bridge","name","My bridge","source","用户维护","download_url","https://example.com/guide"),"1.x",false);Assert(!c.IngestStoreItem(J.D("app_id","demo","pc_dependencies",new object[0])),"store replaced manual app mapping");Assert(c.Requirements("demo").Count==1,"manual requirement lost");c.IngestStoreItem(J.D("app_id","another","pc_dependencies",new[]{J.D("id","bridge","name","Other name")}));Assert(J.Str(c.Dependency("bridge"),"name")=="My bridge","shared manual entry clobbered");c.SetNoExternalDependencies("none","None");Assert(!c.IngestStoreItem(J.D("app_id","none","pc_dependencies",new[]{"Unexpected"})),"manual none overwritten");});
      Check("native hotspot status without exposing password",delegate{var h=Native.Hotspot("Status").GetAwaiter().GetResult();Assert(J.Bool(h,"ok"),"hotspot failed");Assert(J.Get(h,"password")==null,"credential leaked in status");Assert(J.Get(h,"ssid")!=null,"SSID missing");});
      Check("image preparation produces a 320x240 PNG",delegate{
        string dir=Path.Combine(Store.Data,"temp");Directory.CreateDirectory(dir);string source=Path.Combine(dir,"diagnostic-image.png");
        try{var visual=new System.Windows.Media.DrawingVisual();using(var context=visual.RenderOpen()){context.DrawRectangle(System.Windows.Media.Brushes.Green,null,new System.Windows.Rect(0,0,64,128));}var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(64,128,96,96,System.Windows.Media.PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var file=File.Create(source))encoder.Save(file);byte[] prepared=MediaTools.ResizeImage(source);using(var memory=new MemoryStream(prepared)){var output=System.Windows.Media.Imaging.BitmapDecoder.Create(memory,System.Windows.Media.Imaging.BitmapCreateOptions.None,System.Windows.Media.Imaging.BitmapCacheOption.OnLoad);Assert(output.Frames[0].PixelWidth==320&&output.Frames[0].PixelHeight==240,"wrong output dimensions");}}
        finally{if(File.Exists(source))File.Delete(source);}
      });
      if(MediaTools.FindFFmpeg()!="")Check("video transcode produces complete 320x240 MJPEG AVI",delegate{
        string ffmpeg=MediaTools.FindFFmpeg(),dir=Path.Combine(Store.Data,"temp");Directory.CreateDirectory(dir);string source=Path.Combine(dir,"diagnostic-video.mp4"),output="";
        try{MediaTools.Execute(ffmpeg,"-nostdin -hide_banner -loglevel error -f lavfi -i color=c=green:s=640x360:r=25 -t 0.4 -c:v libx264 -pix_fmt yuv420p -y \""+source+"\"",15000).GetAwaiter().GetResult();output=MediaTools.ConvertVideo(source).GetAwaiter().GetResult();string text=MediaTools.Execute(Path.Combine(Path.GetDirectoryName(ffmpeg),"ffprobe.exe"),"-v error -show_entries stream=codec_name,width,height -of json \""+output+"\"",10000).GetAwaiter().GetResult();var stream=J.List(J.Parse(text),"streams").First();Assert(J.Str(stream,"codec_name")=="mjpeg"&&J.Num(stream,"width")==320&&J.Num(stream,"height")==240,"wrong codec or dimensions");}
        finally{if(File.Exists(source))File.Delete(source);if(output!=""&&File.Exists(output))File.Delete(output);}
      });
      Check("SMTC worker, protocol, and shutdown",delegate{
        using(var bridge=new MusicBridge()){
          bridge.Install();int port;var reserve=new TcpListener(IPAddress.Loopback,0);reserve.Start();port=((IPEndPoint)reserve.LocalEndpoint).Port;reserve.Stop();
          bridge.Start("192.168.137.7",port,500,"");
          for(int i=0;i<35;i++){Thread.Sleep(250);var s=bridge.Snapshot();if(J.Str(s,"state")!="waiting"&&J.Str(s,"state")!="stopped")break;if(J.Get(s,"sessions")!=null)break;}
          var snapshot=bridge.Snapshot();Assert(bridge.Running,"worker exited: "+bridge.Error);Assert(J.Get(snapshot,"sessions")!=null,"SMTC never supplied a snapshot: "+bridge.Error);Assert(J.Bool(snapshot,"ok"),J.Str(snapshot,"error","SMTC error"));
          if(args.Contains("--music-live")){
            Check("live QQ Music cover is an 88x88 JPEG",delegate{var live=bridge.Snapshot();Assert(J.Bool(live,"connected")&&J.Str(live,"source_app").IndexOf("QQMusic",StringComparison.OrdinalIgnoreCase)>=0,"QQ Music must be playing");Assert(J.Str(live,"cover_id_text")!="",J.Str(live,"cover_error","cover missing"));using(var client=new HttpClient(new HttpClientHandler {UseProxy=false}))using(var memory=new MemoryStream(client.GetByteArrayAsync("http://127.0.0.1:"+port+"/cover?id="+J.Str(live,"cover_id_text")).GetAwaiter().GetResult()))using(var cover=System.Drawing.Image.FromStream(memory)){Assert(cover.Width==88&&cover.Height==88,"incorrect cover dimensions");Assert(cover.RawFormat.Guid==System.Drawing.Imaging.ImageFormat.Jpeg.Guid,"not JPEG");}});
            Check("live QQ Music lyrics reach the bridge HTTP endpoint",delegate{Assert(OnlineLyrics.Enabled,"online lyric matching must be enabled");for(int attempt=0;attempt<100;attempt++){var pending=bridge.Snapshot();if(J.Str(pending,"lyrics_state")=="ready"||J.Str(pending,"lyrics_state")=="error")break;Thread.Sleep(250);}var live=bridge.Snapshot();Assert(J.Str(live,"lyric_provider")=="qq",J.Str(live,"lyrics_error","QQ lyrics not ready"));using(var client=new HttpClient(new HttpClientHandler {UseProxy=false})){var data=J.Parse(client.GetStringAsync("http://127.0.0.1:"+port+"/lyrics?provider=qq&id="+J.Str(live,"lyric_id_text")).GetAwaiter().GetResult());Assert(J.Bool(data,"ok")&&J.List(data,"lines").Count>0,"lyrics missing");Assert(J.Get(J.List(data,"lines").First(),"at_ms")!=null,"device timestamp protocol missing");}});
          }
          using(var client=new HttpClient(new HttpClientHandler {UseProxy=false})){
            var health=J.Parse(client.GetStringAsync("http://127.0.0.1:"+port+"/health").GetAwaiter().GetResult());Assert(J.Bool(health,"ok"),"health");
            var status=J.Parse(client.GetStringAsync("http://127.0.0.1:"+port+"/status").GetAwaiter().GetResult());Assert(J.Get(status,"connected") is bool,"status schema");Assert(J.Get(status,"cover_b64")==null,"internal thumbnail bytes exposed");
            using(var invalid=client.GetAsync("http://127.0.0.1:"+port+"/control?action=unsupported").GetAwaiter().GetResult())Assert(invalid.StatusCode==HttpStatusCode.BadRequest,"control validation");
          }
          bridge.Stop();Assert(!bridge.Running,"bridge still running");
          var reusable=new TcpListener(IPAddress.Any,port);reusable.Start();reusable.Stop();
        }
      });
      int deviceIndex=Array.IndexOf(args,"--device");if(deviceIndex>=0&&deviceIndex+1<args.Length)Check("live device identity and stored settings read",delegate{using(var d=new DeviceClient(args[deviceIndex+1])){var s=d.Request("/api/system/state").GetAwaiter().GetResult();Assert(DeviceClient.IsDevice(s),"identity mismatch");Assert(J.Bool(J.Map(s,"wifi"),"sta_connected"),"Wi-Fi disconnected");var settings=J.Parse(d.Text(d.FileRoute("/sd/apps/settings.json")).GetAwaiter().GetResult());Assert(settings!=null,"settings missing");Assert(J.List(s,"installed_apps").Count>0,"apps missing");}});
      bool success=results.All(r=>J.Bool(r,"passed"));Store.Atomic(Path.Combine(Store.Data,"diagnostics.json"),J.Stringify(J.D("passed",success,"time",DateTime.Now.ToString("s"),"checks",results)));return success?0:1;
    }
  }
}
